typedef struct { widget_t *user, *pass, *submit; } login_page_t;

void login_page_init(login_page_t *p, widget_t *root) {
    p->user = widget_find(root, "user");
    p->pass = widget_find(root, "pass");
    p->submit = widget_find(root, "submit");
}
void login_page_log_in(login_page_t *p, const char *u, const char *pw) {
    widget_type(p->user, u);
    widget_type(p->pass, pw);
    widget_click(p->submit);
}
